# Jaccard similarity directly, for comparison against the MinHash estimate
def jaccard(a, b):
    return len(a & b) / len(a | b)

print(jaccard({1,2,3}, {2,3,4}))   # 0.5

def hamming_distance(code_a, code_b):
    return bin(code_a ^ code_b).count("1")

print(hamming_distance(0b1011, 0b1001))   # 1, differ in one bit position
